package com.company.platform.inventory.infrastructure;
import com.company.platform.inventory.application.InventoryService;import com.company.platform.inventory.application.ReservationStore;import com.fasterxml.jackson.databind.JsonNode;import java.math.BigDecimal;import java.util.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;
@Component public class FulfillmentEventConsumer {private final InventoryService inventory;public FulfillmentEventConsumer(InventoryService i){inventory=i;}
 @KafkaListener(topics={"order.events","payment.events"},groupId="inventory-service",containerFactory="inventoryKafkaListenerContainerFactory") public void onEvent(JsonNode event){JsonNode payload=event.path("payload");String type=payload.path("eventType").asText(event.path("eventType").asText());if(!"ORDER_CONFIRMED".equals(type)&&!"PAYMENT_PAID".equals(type))return;UUID tenant=parse(event.path("tenantId").asText(null));JsonNode data=payload.path("data");if(tenant==null||data.isMissingNode())throw new IllegalArgumentException("event tenant and payload required");UUID order=parse(data.path("orderId").asText(null));if(order==null)throw new IllegalArgumentException("event orderId required");if("ORDER_CONFIRMED".equals(type)){JsonNode lines=data.path("lines");if(lines.isArray())for(JsonNode line:lines){String product=line.path("sellableProductId").asText(line.path("productId").asText(null));UUID productId=parse(product);BigDecimal q=line.path("quantity").decimalValue();if(productId!=null)inventory.reserveProductForTenant(tenant,productId,order,q,order+"-"+productId);}}else{for(ReservationStore.ReservationRecord r:inventory.reservationsForTenantOrder(tenant,order))inventory.consumeReservationForTenant(tenant,r);}}
 private UUID parse(String s){if(s==null||s.isBlank())return null;try{return UUID.fromString(s);}catch(IllegalArgumentException e){throw new IllegalArgumentException("invalid event UUID",e);}}
}
